package in.kalaimarket;
import java.time.*;import java.util.*;
import com.fasterxml.jackson.databind.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
@Service public class PublicSignalService {
 private final V28Engine engine;private final PublicMarketRepository market;private final AutoSignalRepository signals;private final ScanStateRepository scans;private final FeedLockRepository locks;private final MarketQuoteRepository quotes;private final SignalStrategy observer;private final ObjectMapper json;private final boolean enabled,scalps;
 public PublicSignalService(V28Engine e,PublicMarketRepository m,AutoSignalRepository s,ScanStateRepository f,FeedLockRepository l,MarketQuoteRepository q,SignalStrategy o,ObjectMapper j,@Value("${KMR_PUBLIC_SIGNALS_ENABLED:true}")boolean enabled,@Value("${KMR_PUBLIC_SCALPS_ENABLED:false}")boolean scalps){engine=e;market=m;signals=s;scans=f;locks=l;quotes=q;observer=o;json=j;this.enabled=enabled;this.scalps=scalps;}
 @org.springframework.beans.factory.annotation.Autowired private SignalAuditRecorder audit;
 public boolean enabled(){return enabled;}
 public static boolean metalsOpen(long now){var n=Instant.ofEpochMilli(now).atZone(ZoneId.of("America/New_York"));int day=n.getDayOfWeek().getValue();return day!=6&&(day!=7||n.getHour()>=18)&&(day!=5||n.getHour()<17)&&!(day<=5&&n.getHour()==17);}
 @Transactional public JsonNode ingest(PublicSnapshot request){
  if(!enabled)throw new ResponseStatusException(HttpStatus.CONFLICT,"Independent public scanner is disabled");long now=System.currentTimeMillis();request.validate(now);
  if(locks.lock(request.symbol()).isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Add the public instrument to the watchlist first");
  var existing=market.findById(request.symbol()).orElse(null);
  try{if(existing!=null&&json.readTree(existing.snapshot).path("quoteAt").asLong()>request.quoteAt())throw new IllegalArgumentException("Older public snapshot refused");}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("Stored public history unreadable");}
  var x=new PublicSnapshot(request.symbol(),request.source(),request.quoteAt(),request.price(),request.c5(),request.c15(),request.h1(),request.h4(),request.events(),request.calendarAt(),request.symbol().equals("BTCUSD")||metalsOpen(now),now);
  JsonNode a=engine.analyze(x);var q=new FeedRequest.Quote(Instant.ofEpochMilli(x.quoteAt()),x.price(),x.price());
  var mq=new MarketQuote();mq.symbol=x.symbol();mq.bid=AutoSignal.price(x.price());mq.ask=mq.bid;mq.quotedAt=q.time();mq.source="PUBLIC_REFERENCE";quotes.save(mq);
  for(var signal:signals.findBySymbolAndStatusIn(x.symbol(),List.of(AutoSignal.Status.PENDING,AutoSignal.Status.ACTIVE,AutoSignal.Status.TP1,AutoSignal.Status.TP2,AutoSignal.Status.TP3,AutoSignal.Status.TARGET)))if((signal.strategy.startsWith("KMR_V28")||signal.isManual())&&!signal.finalTargetReached()){signal.activityActor="SYSTEM:PUBLIC_SCANNER";observer.observe(signal,q,Instant.ofEpochMilli(now));}
  saveScan(x,a,Timeframe.M15,"sourceBar",a.path("scan").path("score").asInt(),a.path("reason").asText("Gathering public data"));
  if(a.path("auto").isObject())create(x,a.path("auto"),Timeframe.M15,a.path("sourceBar").asLong(),a.path("scan").path("score").asInt(),"KMR_V28_PUBLIC",q,a);
  if(scalps){String why=a.path("scalp").path("look").asText("Waiting for scalp setup");saveScan(x,a,Timeframe.M5,"scalpBar",0,why);
   if(a.path("scalpPlan").isObject()){JsonNode p=a.path("scalpPlan");var plan=json.createObjectNode();plan.put("dir",a.path("scalp").path("dir").asText());plan.put("atrV",a.path("scalp").path("A").asDouble());plan.put("entry",p.path("entry").asDouble());plan.put("sl",p.path("sl").asDouble());plan.put("tp1",p.path("tp").asDouble());plan.put("tp2",p.path("tp").asDouble());plan.put("tp3",p.path("tp").asDouble());create(x,plan,Timeframe.M5,a.path("scalpBar").asLong(),0,"KMR_V28_SCALP",q,a);}}
  var row=existing==null?new PublicMarketState():existing;row.symbol=x.symbol();row.updatedAt=Instant.ofEpochMilli(now);try{row.snapshot=json.writeValueAsString(x);row.analysis=json.writeValueAsString(a);}catch(Exception e){throw new IllegalStateException("Cannot persist public analysis");}market.save(row);return a;
 }
 private void saveScan(PublicSnapshot x,JsonNode a,Timeframe tf,String bar,int quality,String reason){long t=a.path(bar).asLong();if(t<=0)return;String key=x.symbol()+"|"+tf;var state=scans.findById(key).orElseGet(ScanState::new);state.id=key;state.symbol=x.symbol();state.timeframe=tf;state.lastBar=Instant.ofEpochMilli(t);state.lastScanAt=Instant.now();state.lastQuoteAt=Instant.ofEpochMilli(x.quoteAt());state.receivedAt=Instant.now();state.quality=quality;state.decisionContext=json.convertValue(a,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});state.reason=reason.substring(0,Math.min(reason.length(),255));scans.save(state);}
 private void create(PublicSnapshot x,JsonNode p,Timeframe tf,long bar,int quality,String name,FeedRequest.Quote q,JsonNode analysis){
  Instant sourceBar=Instant.ofEpochMilli(bar);if(signals.existsBySymbolAndTimeframeAndSourceBar(x.symbol(),tf,sourceBar))return;
  if(signals.findBySymbolAndStatusIn(x.symbol(),List.of(AutoSignal.Status.PENDING,AutoSignal.Status.ACTIVE,AutoSignal.Status.TP1,AutoSignal.Status.TP2,AutoSignal.Status.TP3,AutoSignal.Status.TARGET)).stream().anyMatch(s->s.strategy.equals(name)&&s.timeframe==tf&&!s.finalTargetReached()))return;
  var s=new AutoSignal();s.symbol=x.symbol();s.timeframe=tf;s.direction=TradePlan.Direction.valueOf(p.path("dir").asText());s.pendingKind=AutoSignal.PendingKind.MARKET;s.entry=AutoSignal.price(p.path("entry").asDouble());s.stopLoss=AutoSignal.price(p.path("sl").asDouble());s.tp1=AutoSignal.price(p.path("tp1").asDouble());s.tp2=AutoSignal.price(p.path("tp2").asDouble());s.targets=name.equals("KMR_V28_SCALP")?List.of(s.tp1):List.of(s.tp1,s.tp2,AutoSignal.price(p.path("tp3").asDouble()));s.sourceAtr=p.path("atrV").asDouble()>0?p.path("atrV").asDouble():null;s.quality=quality;s.reason=(name.equals("KMR_V28_SCALP")?analysis.path("scalp").path("setup").asText("Scalp setup"):analysis.path("reason").asText("v28 setup"));s.reason=s.reason.substring(0,Math.min(255,s.reason.length()));s.decisionContext=json.convertValue(analysis,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});s.decisionContext.put("engineVersion","V28");s.decisionContext.put("evaluatedAt",Instant.ofEpochMilli(x.now()).toString());s.strategy=name;s.sourceBar=sourceBar;s.createdAt=Instant.now();s.updatedAt=s.createdAt;s.lastQuoteAt=q.time();s.expiresAt=s.createdAt.plusSeconds(tf==Timeframe.M5?120:180);
  boolean buy=s.direction==TradePlan.Direction.BUY;if(s.entry.signum()<=0||s.stopLoss.signum()<=0||s.tp1.signum()<=0||(buy?s.stopLoss.compareTo(s.entry)>=0||s.tp1.compareTo(s.entry)<=0:s.stopLoss.compareTo(s.entry)<=0||s.tp1.compareTo(s.entry)>=0))return;signals.save(s);
 }
 public JsonNode analysis(String symbol){var row=market.findById(symbol).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Public data is not loaded yet; MT5 is not required"));try{var result=engine.analyze(json.readValue(row.snapshot,PublicSnapshot.class));if(audit!=null)audit.manualAnalysis(symbol,result);return result;}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("Stored public history is unreadable");}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}}
}
